// waitAllDelivered collects count deliveries from every node in parallel,
// returning an error on timeout. Uses context cancellation so all goroutines
// unblock promptly when the deadline fires (a single time.After channel would
// only wake one goroutine).
func waitAllDelivered(nodes []*App, count int, timeout time.Duration) error {
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	errCh := make(chan error, len(nodes))
	var wg sync.WaitGroup
	for i, n := range nodes {
		wg.Add(1)
		go func(idx int, app *App) {
			defer wg.Done()
			for c := 0; c < count; c++ {
				select {
				case <-app.Delivered:
				case <-ctx.Done():
					errCh <- fmt.Errorf("node %d timed out waiting for delivery %d/%d", idx+1, c+1, count)
					return
				}
			}
		}(i, n)
	}
	wg.Wait()
	close(errCh)
	for err := range errCh {
		if err != nil {
			return err
		}
	}
	return nil
}

