// update_view, update_decisions, vc_same_seq events.
func TestTLATraceViewChange(t *testing.T) {
	t.Parallel()

	tracesDir := "/Users/tess/dev/Specula/case-studies/smartbft/.specula-output/traces"
	if err := os.MkdirAll(tracesDir, 0o755); err != nil {
		t.Fatalf("failed to create traces dir: %v", err)
	}
	bft.InitTLATrace("/Users/tess/dev/Specula/case-studies/smartbft/.specula-output/traces/trace_view_change.ndjson")
	defer bft.CloseTLATrace()

	network := NewNetwork()
	defer network.Shutdown()

	testDir, err := os.MkdirTemp("", t.Name())
	if err != nil {
		t.Fatalf("generate temporary test dir: %v", err)
	}
	defer os.RemoveAll(testDir)

	const numberOfNodes = 4
	nodes := make([]*App, 0, numberOfNodes)

	start := time.Now()
	for i := 1; i <= numberOfNodes; i++ {
		n := newNode(uint64(i), network, t.Name(), testDir, false, 0)
		n.heartbeatTime = make(chan time.Time, 200)
		n.heartbeatTime <- start
		n.viewChangeTime = make(chan time.Time, 200)
		n.viewChangeTime <- start
		n.Setup()
		nodes = append(nodes, n)
	}
	startNodes(nodes, network)

	// Submit one proposal and wait for all nodes to deliver it.
	nodes[0].Submit(Request{ID: "1", ClientID: "alice"})
	if err := waitAllDelivered(nodes, 1, 30*time.Second); err != nil {
		t.Logf("initial delivery: %v (continuing)", err)
	}

	// Isolate the leader (node 1, index 0) from the other nodes.
	for i := 2; i <= numberOfNodes; i++ {
		nodes[0].DisconnectFrom(uint64(i))
	}

	// Drive time forward so followers detect the missing heartbeat and initiate
	// a view change.
	done := make(chan struct{})
	defer close(done)
	var counter uint64
	accelerateTime(nodes[1:], done, true, true, &counter)

	// Submit from node 2 to trigger request forwarding and view-change delivery.
	nodes[1].Submit(Request{ID: "2", ClientID: "alice"})

	// Wait for the non-leader nodes to deliver the second proposal.
	if err := waitAllDelivered(nodes[1:], 1, 120*time.Second); err != nil {
		t.Logf("view-change delivery: %v (trace still written)", err)
	}
