// TestTLATraceHBTimeout records a heartbeat-timeout trace: a manual clock is
// used to advance time past LeaderHeartbeatTimeout so that the hb_timeout event
// fires on followers without any real-time waiting.
//
// fastConfig has LeaderHeartbeatTimeout = 1 minute, so two ticks of 90 s each
// push followers past the threshold.
func TestTLATraceHBTimeout(t *testing.T) {
	t.Parallel()

	tracesDir := "/Users/tess/dev/Specula/case-studies/smartbft/.specula-output/traces"
	if err := os.MkdirAll(tracesDir, 0o755); err != nil {
		t.Fatalf("failed to create traces dir: %v", err)
	}
	bft.InitTLATrace("/Users/tess/dev/Specula/case-studies/smartbft/.specula-output/traces/trace_hb_timeout.ndjson")
	defer bft.CloseTLATrace()

	network := NewNetwork()
	defer network.Shutdown()

	testDir, err := os.MkdirTemp("", t.Name())
	if err != nil {
		t.Fatalf("generate temporary test dir: %v", err)
	}
	defer os.RemoveAll(testDir)

	const numberOfNodes = 4
	nodes := make([]*App, 0, numberOfNodes)

	t0 := time.Now()

	for i := 1; i <= numberOfNodes; i++ {
		n := newNode(uint64(i), network, t.Name(), testDir, false, 0)
		// Install a manual heartbeat clock.  Buffer of 200 prevents sends from
		// blocking when the goroutine is advancing the clock.
		n.heartbeatTime = make(chan time.Time, 200)
		n.heartbeatTime <- t0
		// Also install a manual view-change clock so we can drive view changes.
		n.viewChangeTime = make(chan time.Time, 200)
		n.viewChangeTime <- t0
		// Re-run Setup so that the Consensus struct picks up the manual channels.
		// Note: do NOT call n.Consensus.Stop() here — Consensus was created by
		// newNode but never started, so Stop() would panic on nil ViewChanger.
		n.Setup()
		nodes = append(nodes, n)
	}

	}

	startNodes(nodes, network)

	// Disconnect the leader so it does not suppress heartbeat-timeout events on
	// the followers.
	nodes[0].Disconnect()

	// Pump ticks with timestamps spaced 90 s apart.  Two such ticks push every
	// follower past the 1-minute LeaderHeartbeatTimeout.
	for tick := 1; tick <= 5; tick++ {
		ts := t0.Add(time.Duration(tick) * 90 * time.Second)
		for _, n := range nodes[1:] {
			select {
			case n.heartbeatTime <- ts:
			default:
			}
			select {
			case n.viewChangeTime <- ts:
			default:
			}
		}
		// Small sleep to let the consensus goroutines process each tick.
		time.Sleep(20 * time.Millisecond)
	}

	// After the timeout fires, reconnect the leader so the cluster can finish a
	// view change and deliver at least one proposal.
	nodes[0].Connect()
	nodes[1].Submit(Request{ID: "1", ClientID: "alice"})

	if err := waitAllDelivered(nodes[1:], 1, 60*time.Second); err != nil {
		t.Logf("hb_timeout delivery: %v (trace still written)", err)
	}
}

