// for view 1) has NOT yet committed seq 1 when the view change occurs, so it
// receives a VIEW_DATA with last_seq = CommittedSeq(node2)+1. This triggers the
// vc_deliver and vc_validate events (the deliver-before-validate Family 2 path).
//
// Setup:
//  1. Disconnect node 2 (future view-1 leader) so it does not commit seq 1.
//  2. Nodes 1, 3, 4 form quorum (3 of 4) and commit seq 1.
//  3. Disconnect node 1 (original leader), reconnect node 2.
//  4. Trigger view change; node 2 becomes leader in view 1.
//  5. Nodes 3 and 4 send VIEW_DATA with last_seq=1 to node 2 (last_seq=0).
//     First VIEW_DATA → vc_deliver + vc_validate; second → vc_same_seq.
func TestTLATraceVCDeliver(t *testing.T) {
	t.Parallel()

	tracesDir := "/Users/tess/dev/Specula/case-studies/smartbft/.specula-output/traces"
	if err := os.MkdirAll(tracesDir, 0o755); err != nil {
		t.Fatalf("failed to create traces dir: %v", err)
	}
	bft.InitTLATrace("/Users/tess/dev/Specula/case-studies/smartbft/.specula-output/traces/trace_vc_deliver.ndjson")
	defer bft.CloseTLATrace()

	network := NewNetwork()
	defer network.Shutdown()

	testDir, err := os.MkdirTemp("", t.Name())
	if err != nil {
		t.Fatalf("generate temporary test dir: %v", err)
	}
	defer os.RemoveAll(testDir)

	const numberOfNodes = 4
	nodes := make([]*App, 0, numberOfNodes)

	start := time.Now()
	for i := 1; i <= numberOfNodes; i++ {
		n := newNode(uint64(i), network, t.Name(), testDir, false, 0)
		n.heartbeatTime = make(chan time.Time, 200)
		n.heartbeatTime <- start
		n.viewChangeTime = make(chan time.Time, 200)
		n.viewChangeTime <- start
		n.Setup()
		nodes = append(nodes, n)
	}
	startNodes(nodes, network)

	// Disconnect node 2 (future view-1 leader) before seq 1 is committed.
	// Nodes 1, 3, 4 will reach quorum (3 of 4) and commit seq 1; node 2 stays at seq 0.
	nodes[1].Disconnect()

	nodes[0].Submit(Request{ID: "1", ClientID: "alice"})
	if err := waitAllDelivered([]*App{nodes[0], nodes[2], nodes[3]}, 1, 15*time.Second); err != nil {
		t.Logf("initial delivery (exc node2): %v (continuing)", err)
	}

	// Disconnect the original leader (node 1) and reconnect node 2.
	nodes[0].Disconnect()
	nodes[1].Connect()

	// Accelerate time on nodes 2, 3, 4 to trigger heartbeat timeout and view change.
	done := make(chan struct{})
	defer close(done)
	var counter uint64
	accelerateTime(nodes[1:], done, true, true, &counter)

	// Submit from node 3 so the new leader (node 2) has a proposal ready after VC.
	nodes[2].Submit(Request{ID: "2", ClientID: "alice"})

	// Wait for nodes 2, 3, 4 to deliver seq 2 in view 1.
	if err := waitAllDelivered(nodes[1:], 1, 120*time.Second); err != nil {
		t.Logf("vc_deliver delivery: %v (trace still written)", err)
	}
}

